message.content:
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Elena Moreau — Editorial, Portrait & Architectural Photographer</title>
  <meta name="description" content="Portfolio of Elena Moreau, freelance editorial, portrait, and architectural photographer based between Paris and New York." />

  <!-- Editorial Typography -->
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;0,600;1,300;1,400&family=Inter:wght@300;400;500&display=swap" rel="stylesheet" />

  <style>
    /* ==========================================================================
       Design Tokens & Base Setup
       ========================================================================== */
    :root {
      --bg: #F6F5F0;
      --bg-elevated: #EFECE4;
      --ink: #141413;
      --ink-muted: #65635C;
      --ink-light: #9A978E;
      --border: rgba(20, 20, 19, 0.12);
      --border-strong: rgba(20, 20, 19, 0.28);
      --accent: #8A6B4E;
      --dark-bg: #0E0E0D;
      --dark-ink: #F4F2EC;

      --font-serif: 'Cormorant Garamond', Georgia, 'Times New Roman', serif;
      --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;

      --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
      --container: 1380px;
      --nav-height: 76px;
    }

    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    html {
      scroll-behavior: smooth;
      font-size: 16px;
      background-color: var(--bg);
      color: var(--ink);
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    body {
      font-family: var(--font-sans);
      font-weight: 300;
      line-height: 1.6;
      background-color: var(--bg);
      color: var(--ink);
      overflow-x: hidden;
    }

    body.no-scroll {
      overflow: hidden;
    }

    img {
      display: block;
      max-width: 100%;
      height: auto;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button, input, textarea, select {
      font: inherit;
      color: inherit;
      background: none;
      border: none;
    }

    button {
      cursor: pointer;
    }

    :focus-visible {
      outline: 1.5px solid var(--ink);
      outline-offset: 3px;
    }

    /* Utility Classes */
    .container {
      width: 100%;
      max-width: var(--container);
      margin-inline: auto;
      padding-inline: clamp(1.25rem, 4vw, 3.5rem);
    }

    .eyebrow {
      font-family: var(--font-sans);
      font-size: 0.72rem;
      font-weight: 400;
      letter-spacing: 0.16em;
      text-transform: uppercase;
      color: var(--ink-muted);
    }

    .serif {
      font-family: var(--font-serif);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    /* Scroll Progress Bar */
    .scroll-progress {
      position: fixed;
      top: 0;
      left: 0;
      height: 2px;
      width: 0%;
      background: var(--ink);
      z-index: 120;
      pointer-events: none;
      transition: width 0.08s linear;
    }

    /* ==========================================================================
       Navigation
       ========================================================================== */
    .site-header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      height: var(--nav-height);
      z-index: 100;
      transition: background-color 0.35s var(--ease-out), border-color 0.35s var(--ease-out);
      border-bottom: 1px solid transparent;
    }

    .site-header.scrolled {
      background-color: rgba(246, 245, 240, 0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom-color: var(--border);
    }

    .nav-inner {
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 2rem;
    }

    .brand {
      display: flex;
      align-items: baseline;
      gap: 0.75rem;
    }

    .brand-name {
      font-family: var(--font-serif);
      font-size: 1.55rem;
      font-weight: 400;
      letter-spacing: 0.02em;
      line-height: 1;
    }

    .brand-tag {
      font-size: 0.68rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--ink-muted);
      display: none;
    }

    @media (min-width: 900px) {
      .brand-tag {
        display: inline-block;
      }
    }

    .nav-links {
      display: none;
      align-items: center;
      gap: 2.5rem;
      list-style: none;
    }

    @media (min-width: 768px) {
      .nav-links {
        display: flex;
      }
    }

    .nav-links a {
      font-size: 0.78rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--ink-muted);
      position: relative;
      padding-block: 0.25rem;
      transition: color 0.25s ease;
    }

    .nav-links a::after {
      content: '';
      position: absolute;
      left: 0;
      bottom: 0;
      width: 100%;
      height: 1px;
      background: var(--ink);
      transform: scaleX(0);
      transform-origin: right;
      transition: transform 0.35s var(--ease-out);
    }

    .nav-links a:hover,
    .nav-links a.active {
      color: var(--ink);
    }

    .nav-links a:hover::after,
    .nav-links a.active::after {
      transform: scaleX(1);
      transform-origin: left;
    }

    .nav-cta {
      font-size: 0.74rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      padding: 0.65rem 1.25rem;
      border: 1px solid var(--border-strong);
      border-radius: 999px;
      transition: background-color 0.3s ease, color 0.3s ease, border-color 0.3s ease;
    }

    .nav-cta:hover {
      background-color: var(--ink);
      color: var(--bg);
      border-color: var(--ink);
    }

    /* Mobile Hamburger */
    .menu-toggle {
      display: flex;
      flex-direction: column;
      justify-content: center;
      gap: 6px;
      width: 36px;
      height: 36px;
      padding: 4px;
      z-index: 110;
    }

    @media (min-width: 768px) {
      .menu-toggle {
        display: none;
      }
    }

    .menu-toggle span {
      display: block;
      width: 100%;
      height: 1px;
      background-color: var(--ink);
      transition: transform 0.35s var(--ease-out), opacity 0.25s ease;
    }

    .menu-toggle[aria-expanded="true"] span:first-child {
      transform: translateY(3.5px) rotate(45deg);
    }

    .menu-toggle[aria-expanded="true"] span:last-child {
      transform: translateY(-3.5px) rotate(-45deg);
    }

    .mobile-drawer {
      position: fixed;
      inset: 0;
      background: var(--bg);
      z-index: 95;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      padding: 6.5rem 1.75rem 2.5rem;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.35s var(--ease-out);
    }

    .mobile-drawer.open {
      opacity: 1;
      pointer-events: auto;
    }

    .mobile-nav-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 1.25rem;
    }

    .mobile-nav-list a {
      font-family: var(--font-serif);
      font-size: clamp(2.25rem, 9vw, 3.25rem);
      font-weight: 300;
      line-height: 1.1;
      display: inline-block;
    }

    .mobile-drawer-footer {
      border-top: 1px solid var(--border);
      padding-top: 1.5rem;
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
      font-size: 0.85rem;
      color: var(--ink-muted);
    }

    /* ==========================================================================
       Hero Section
       ========================================================================== */
    .hero {
      padding-top: calc(var(--nav-height) + clamp(2.5rem, 6vh, 5rem));
      padding-bottom: clamp(4rem, 9vh, 7.5rem);
      border-bottom: 1px solid var(--border);
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: clamp(2.5rem, 5vw, 4.5rem);
      align-items: end;
    }

    @media (min-width: 960px) {
      .hero-grid {
        grid-template-columns: 1.05fr 0.95fr;
        align-items: center;
      }
    }

    .hero-content {
      display: flex;
      flex-direction: column;
      gap: 1.75rem;
    }

    .availability-pill {
      display: inline-flex;
      align-items: center;
      gap: 0.6rem;
      width: fit-content;
      padding: 0.4rem 0.9rem;
      border: 1px solid var(--border);
      border-radius: 999px;
      font-size: 0.72rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--ink-muted);
    }

    .status-dot {
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background-color: #4A7C59;
      box-shadow: 0 0 0 3px rgba(74, 124, 89, 0.18);
    }

    .hero-title {
      font-family: var(--font-serif);
      font-size: clamp(3rem, 6.4vw, 5.8rem);
      font-weight: 300;
      line-height: 0.98;
      letter-spacing: -0.02em;
      color: var(--ink);
    }

    .hero-title em {
      font-style: italic;
      color: var(--accent);
    }

    .hero-lead {
      max-width: 46ch;
      font-size: clamp(0.98rem, 1.3vw, 1.08rem);
      color: var(--ink-muted);
      line-height: 1.7;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 1.25rem 2rem;
      padding-top: 0.5rem;
    }

    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      padding: 0.95rem 1.8rem;
      background-color: var(--ink);
      color: var(--bg);
      font-size: 0.75rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      border-radius: 999px;
      transition: transform 0.3s var(--ease-out), background-color 0.3s ease;
    }

    .btn-primary:hover {
      background-color: #2A2926;
      transform: translateY(-2px);
    }

    .btn-text {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.76rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--ink);
      padding-bottom: 0.25rem;
      border-bottom: 1px solid var(--border-strong);
      transition: border-color 0.25s ease, gap 0.25s ease;
    }

    .btn-text:hover {
      border-color: var(--ink);
      gap: 0.8rem;
    }

    .hero-meta {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1.25rem;
      padding-top: 2rem;
      margin-top: 1rem;
      border-top: 1px solid var(--border);
    }

    .meta-label {
      display: block;
      font-size: 0.68rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--ink-light);
      margin-bottom: 0.25rem;
    }

    .meta-value {
      font-family: var(--font-serif);
      font-size: 1.15rem;
      color: var(--ink);
    }

    /* Hero Featured Frame */
    .hero-visual {
      position: relative;
    }

    .hero-frame {
      position: relative;
      aspect-ratio: 4 / 5;
      overflow: hidden;
      background-color: var(--bg-elevated);
      cursor: pointer;
    }

    .hero-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 1.1s var(--ease-out);
    }

    .hero-frame:hover img {
      transform: scale(1.03);
    }

    .hero-caption {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      gap: 1rem;
      padding-top: 0.85rem;
      font-size: 0.76rem;
      color: var(--ink-muted);
    }

    .hero-caption strong {
      font-family: var(--font-serif);
      font-size: 1rem;
      font-weight: 400;
      font-style: italic;
      color: var(--ink);
    }

    /* ==========================================================================
       Selected Work / Portfolio Section
       ========================================================================== */
    .section {
      padding-block: clamp(4.5rem, 9vw, 8rem);
      border-bottom: 1px solid var(--border);
    }

    .section-header {
      display: flex;
      flex-direction: column;
      gap: 1.5rem;
      margin-bottom: clamp(2.5rem, 5vw, 4rem);
    }

    @media (min-width: 860px) {
      .section-header.split {
        flex-direction: row;
        align-items: flex-end;
        justify-content: space-between;
      }
    }

    .section-title {
      font-family: var(--font-serif);
      font-size: clamp(2.4rem, 4.8vw, 4rem);
      font-weight: 300;
      line-height: 1.05;
      letter-spacing: -0.015em;
      margin-top: 0.5rem;
    }

    /* Filter Bar & View Toggle */
    .work-controls {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1.25rem;
      padding-bottom: 1.5rem;
      margin-bottom: 2.5rem;
      border-bottom: 1px solid var(--border);
    }

    .filter-group {
      display: flex;
      flex-wrap: wrap;
      gap: 0.45rem;
    }

    .filter-btn {
      padding: 0.5rem 1.05rem;
      border-radius: 999px;
      font-size: 0.74rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--ink-muted);
      border: 1px solid transparent;
      transition: all 0.25s ease;
    }

    .filter-btn:hover {
      color: var(--ink);
      border-color: var(--border);
    }

    .filter-btn.active {
      background-color: var(--ink);
      color: var(--bg);
      border-color: var(--ink);
    }

    .filter-count {
      font-size: 0.65rem;
      opacity: 0.65;
      margin-left: 0.25rem;
    }

    .view-toggle {
      display: inline-flex;
      border: 1px solid var(--border);
      border-radius: 999px;
      padding: 3px;
    }

    .view-btn {
      padding: 0.35rem 0.9rem;
      border-radius: 999px;
      font-size: 0.7rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: var(--ink-muted);
      transition: all 0.25s ease;
    }

    .view-btn.active {
      background: var(--bg-elevated);
      color: var(--ink);
    }

    /* Editorial Masonry / Curated Grid */
    .gallery-grid {
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      gap: clamp(1.5rem, 3vw, 3rem) clamp(1.25rem, 2.5vw, 2.5rem);
      align-items: start;
    }

    .gallery-item {
      grid-column: span 12;
      display: flex;
      flex-direction: column;
      gap: 0.85rem;
      cursor: pointer;
      transition: opacity 0.4s ease, transform 0.5s var(--ease-out);
    }

    @media (min-width: 640px) {
      .gallery-item {
        grid-column: span 6;
      }
    }

    @media (min-width: 980px) {
      .gallery-item.layout-wide {
        grid-column: span 7;
      }
      .gallery-item.layout-narrow {
        grid-column: span 5;
      }
      .gallery-item.layout-third {
        grid-column: span 4;
      }
      .gallery-item.layout-half {
        grid-column: span 6;
      }
      .gallery-item.offset-top {
        margin-top: 3.5rem;
      }
    }

    .photo-frame {
      position: relative;
      overflow: hidden;
      background-color: var(--bg-elevated);
      aspect-ratio: 4 / 5;
    }

    .gallery-item.aspect-landscape .photo-frame {
      aspect-ratio: 3 / 2;
    }

    .gallery-item.aspect-square .photo-frame {
      aspect-ratio: 1 / 1;
    }

    .gallery-item.aspect-tall .photo-frame {
      aspect-ratio: 3 / 4;
    }

    .photo-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      opacity: 0;
      transform: scale(1.02);
      transition: transform 0.9s var(--ease-out), opacity 0.6s ease, filter 0.5s ease;
    }

    .photo-frame img.loaded {
      opacity: 1;
      transform: scale(1);
    }

    .gallery-item:hover .photo-frame img.loaded {
      transform: scale(1.045);
    }

    .photo-frame.is-monochrome img {
      filter: grayscale(100%) contrast(1.12);
    }

    .photo-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(14, 14, 13, 0.52) 0%, transparent 45%);
      opacity: 0;
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      padding: 1.25rem;
      color: var(--dark-ink);
      transition: opacity 0.35s ease;
    }

    .gallery-item:hover .photo-overlay {
      opacity: 1;
    }

    .photo-expand {
      font-size: 0.7rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      padding: 0.4rem 0.8rem;
      border: 1px solid rgba(244, 242, 236, 0.45);
      border-radius: 999px;
      backdrop-filter: blur(4px);
    }

    .photo-meta {
      display: flex;
      justify-content: space-between;
      align-items: baseline;
      gap: 1rem;
    }

    .photo-title {
      font-family: var(--font-serif);
      font-size: 1.35rem;
      font-weight: 400;
      line-height: 1.2;
      color: var(--ink);
    }

    .photo-sub {
      font-size: 0.74rem;
      color: var(--ink-muted);
      letter-spacing: 0.04em;
      margin-top: 0.15rem;
    }

    .photo-year {
      font-size: 0.72rem;
      letter-spacing: 0.1em;
      color: var(--ink-light);
      white-space: nowrap;
    }

    /* Index / Archive List View */
    .gallery-index {
      display: none;
      flex-direction: column;
      border-top: 1px solid var(--border);
    }

    .gallery-index.active {
      display: flex;
    }

    .gallery-grid.hidden {
      display: none;
    }

    .index-row {
      display: grid;
      grid-template-columns: 56px 1.6fr 1fr auto;
      align-items: center;
      gap: 1.25rem;
      padding: 1.15rem 0.5rem;
      border-bottom: 1px solid var(--border);
      cursor: pointer;
      transition: background-color 0.25s ease, padding-inline 0.25s ease;
    }

    .index-row:hover {
      background-color: var(--bg-elevated);
      padding-inline: 1rem;
    }

    .index-thumb {
      width: 52px;
      height: 52px;
      object-fit: cover;
      background: var(--bg-elevated);
    }

    .index-thumb.is-monochrome {
      filter: grayscale(100%) contrast(1.12);
    }

    .index-title {
      font-family: var(--font-serif);
      font-size: 1.35rem;
      font-weight: 400;
    }

    .index-details {
      font-size: 0.8rem;
      color: var(--ink-muted);
      display: none;
    }

    @media (min-width: 720px) {
      .index-details {
        display: block;
      }
    }

    .index-cat {
      font-size: 0.7rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--ink-muted);
      text-align: right;
    }

    /* ==========================================================================
       About & Editorial Statement
       ========================================================================== */
    .about-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: clamp(2.5rem, 6vw, 6rem);
      align-items: start;
    }

    @media (min-width: 900px) {
      .about-grid {
        grid-template-columns: 0.85fr 1.15fr;
      }
    }

    .portrait-card {
      position: relative;
    }

    .portrait-frame {
      aspect-ratio: 4 / 5;
      overflow: hidden;
      background: var(--bg-elevated);
    }

    .portrait-frame img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      filter: contrast(1.03);
    }

    .portrait-note {
      margin-top: 1rem;
      font-size: 0.75rem;
      color: var(--ink-muted);
      display: flex;
      justify-content: space-between;
      border-top: 1px solid var(--border);
      padding-top: 0.75rem;
    }

    .about-copy {
      display: flex;
      flex-direction: column;
      gap: 1.5rem;
    }

    .pull-quote {
      font-family: var(--font-serif);
      font-size: clamp(1.75rem, 3vw, 2.55rem);
      font-weight: 300;
      line-height: 1.22;
      color: var(--ink);
    }

    .pull-quote em {
      font-style: italic;
      color: var(--accent);
    }

    .about-text {
      color: var(--ink-muted);
      font-size: 0.98rem;
      line-height: 1.78;
      max-width: 60ch;
    }

    .credentials-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 2rem;
      margin-top: 1.5rem;
      padding-top: 2rem;
      border-top: 1px solid var(--border);
    }

    @media (min-width: 600px) {
      .credentials-grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    .credential-list {
      list-style: none;
      margin-top: 0.85rem;
      display: flex;
      flex-direction: column;
      gap: 0.45rem;
      font-size: 0.9rem;
      color: var(--ink);
    }

    .credential-list li {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      padding-bottom: 0.45rem;
      border-bottom: 1px dashed var(--border);
    }

    .credential-list span {
      color: var(--ink-light);
      font-size: 0.78rem;
    }

    /* ==========================================================================
       Services / Commissions
       ========================================================================== */
    .services-grid {
      display: grid;
      grid-template-columns: 1fr;
      border-top: 1px solid var(--border);
    }

    @media (min-width: 860px) {
      .services-grid {
        grid-template-columns: repeat(3, 1fr);
      }
    }

    .service-card {
      padding: clamp(2rem, 4vw, 3rem) 0;
      border-bottom: 1px solid var(--border);
      display: flex;
      flex-direction: column;
      gap: 1.1rem;
    }

    @media (min-width: 860px) {
      .service-card {
        padding: clamp(2rem, 3.5vw, 3rem);
        border-bottom: none;
        border-right: 1px solid var(--border);
      }
      .service-card:first-child {
        padding-left: 0;
      }
      .service-card:last-child {
        border-right: none;
        padding-right: 0;
      }
    }

    .service-num {
      font-family: var(--font-serif);
      font-size: 1.15rem;
      font-style: italic;
      color: var(--accent);
    }

    .service-title {
      font-family: var(--font-serif);
      font-size: 1.85rem;
      font-weight: 400;
      line-height: 1.15;
    }

    .service-desc {
      font-size: 0.92rem;
      color: var(--ink-muted);
      line-height: 1.7;
    }

    .service-deliverables {
      margin-top: auto;
      padding-top: 1rem;
      font-size: 0.74rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--ink-light);
    }

    /* ==========================================================================
       Contact & Inquiry Section
       ========================================================================== */
    .contact-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: clamp(3rem, 6vw, 5.5rem);
    }

    @media (min-width: 900px) {
      .contact-grid {
        grid-template-columns: 0.95fr 1.05fr;
      }
    }

    .contact-direct {
      display: flex;
      flex-direction: column;
      gap: 2rem;
    }

    .email-block {
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
      padding-top: 0.5rem;
    }

    .email-link {
      font-family: var(--font-serif);
      font-size: clamp(1.75rem, 3.4vw, 2.65rem);
      font-weight: 300;
      line-height: 1.1;
      border-bottom: 1px solid var(--border-strong);
      width: fit-content;
      padding-bottom: 0.2rem;
      transition: color 0.25s ease, border-color 0.25s ease;
    }

    .email-link:hover {
      color: var(--accent);
      border-color: var(--accent);
    }

    .copy-btn {
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
      width: fit-content;
      font-size: 0.72rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--ink-muted);
      padding: 0.35rem 0;
      transition: color 0.2s ease;
    }

    .copy-btn:hover {
      color: var(--ink);
    }

    .studio-details {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 1.5rem;
      padding-top: 1.5rem;
      border-top: 1px solid var(--border);
      font-size: 0.88rem;
      color: var(--ink-muted);
    }

    .studio-details strong {
      display: block;
      font-weight: 400;
      font-size: 0.7rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--ink-light);
      margin-bottom: 0.35rem;
    }

    /* Inquiry Form */
    .inquiry-form {
      display: flex;
      flex-direction: column;
      gap: 1.5rem;
      background: var(--bg-elevated);
      padding: clamp(1.75rem, 4vw, 3rem);
    }

    .form-row {
      display: grid;
      grid-template-columns: 1fr;
      gap: 1.5rem;
    }

    @media (min-width: 600px) {
      .form-row {
        grid-template-columns: 1fr 1fr;
      }
    }

    .field {
      display: flex;
      flex-direction: column;
      gap: 0.45rem;
    }

    .field label {
      font-size: 0.7rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      color: var(--ink-muted);
    }

    .field input,
    .field select,
    .field textarea {
      width: 100%;
      padding: 0.75rem 0;
      border-bottom: 1px solid var(--border-strong);
      font-size: 0.95rem;
      color: var(--ink);
      background: transparent;
      transition: border-color 0.25s ease;
      border-radius: 0;
    }

    .field input:focus,
    .field select:focus,
    .field textarea:focus {
      outline: none;
      border-bottom-color: var(--ink);
    }

    .field textarea {
      resize: vertical;
      min-height: 110px;
    }

    .form-footer {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      padding-top: 0.5rem;
    }

    .form-note {
      font-size: 0.78rem;
      color: var(--ink-muted);
    }

    .form-status {
      font-size: 0.85rem;
      padding: 0.9rem 1.1rem;
      border: 1px solid var(--border-strong);
      background: var(--bg);
      display: none;
    }

    .form-status.visible {
      display: block;
    }

    /* ==========================================================================
       Footer
       ========================================================================== */
    .site-footer {
      padding-block: 2.5rem;
      font-size: 0.78rem;
      color: var(--ink-muted);
    }

    .footer-inner {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 1.25rem;
    }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 1.5rem;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      font-size: 0.7rem;
    }

    .footer-links a:hover {
      color: var(--ink);
    }

    /* ==========================================================================
       Full-Screen Museum Lightbox
       ========================================================================== */
    .lightbox {
      position: fixed;
      inset: 0;
      z-index: 200;
      background-color: rgba(11, 11, 10, 0.97);
      color: var(--dark-ink);
      display: flex;
      flex-direction: column;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.35s var(--ease-out);
    }

    .lightbox.open {
      opacity: 1;
      pointer-events: auto;
    }

    .lightbox-bar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 1.25rem clamp(1.25rem, 3.5vw, 2.5rem);
      border-bottom: 1px solid rgba(244, 242, 236, 0.1);
      font-size: 0.74rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
    }

    .lightbox-close {
      padding: 0.45rem 1rem;
      border: 1px solid rgba(244, 242, 236, 0.25);
      border-radius: 999px;
      color: var(--dark-ink);
      font-size: 0.7rem;
      letter-spacing: 0.14em;
      text-transform: uppercase;
      transition: background-color 0.25s ease, color 0.25s ease;
    }

    .lightbox-close:hover {
      background: var(--dark-ink);
      color: var(--dark-bg);
    }

    .lightbox-stage {
      flex: 1;
      min-height: 0;
      position: relative;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: clamp(1rem, 3vw, 2.5rem);
    }

    .lightbox-img {
      max-width: 100%;
      max-height: 100%;
      object-fit: contain;
      user-select: none;
      transition: opacity 0.28s ease;
    }

    .lightbox-img.is-monochrome {
      filter: grayscale(100%) contrast(1.12);
    }

    .lightbox-nav {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: 1px solid rgba(244, 242, 236, 0.2);
      background: rgba(14, 14, 13, 0.55);
      color: var(--dark-ink);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.2rem;
      transition: background-color 0.25s ease, border-color 0.25s ease;
    }

    .lightbox-nav:hover {
      background: rgba(244, 242, 236, 0.15);
      border-color: rgba(244, 242, 236, 0.6);
    }

    .lightbox-prev {
      left: clamp(0.75rem, 2.5vw, 2rem);
    }

    .lightbox-next {
      right: clamp(0.75rem, 2.5vw, 2rem);
    }

    .lightbox-caption {
      padding: 1.25rem clamp(1.25rem, 3.5vw, 2.5rem) 1.6rem;
      border-top: 1px solid rgba(244, 242, 236, 0.1);
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      justify-content: space-between;
      gap: 0.75rem 2rem;
    }

    .lightbox-title {
      font-family: var(--font-serif);
      font-size: clamp(1.35rem, 2.2vw, 1.85rem);
      font-weight: 300;
    }

    .lightbox-story {
      font-size: 0.85rem;
      color: rgba(244, 242, 236, 0.68);
      margin-top: 0.2rem;
    }

    .lightbox-specs {
      font-size: 0.72rem;
      letter-spacing: 0.12em;
      text-transform: uppercase;
      color: rgba(244, 242, 236, 0.55);
    }

    /* ==========================================================================
       Scroll Reveal Animations
       ========================================================================== */
    .reveal {
      opacity: 0;
      transform: translateY(22px);
      transition: opacity 0.85s var(--ease-out), transform 0.85s var(--ease-out);
    }

    .reveal.visible {
      opacity: 1;
      transform: translateY(0);
    }

    @media (prefers-reduced-motion: reduce) {
      html { scroll-behavior: auto; }
      .reveal { opacity: 1; transform: none; transition: none; }
      *, *::before, *::after { transition-duration: 0.01ms !important; }
    }
  </style>
</head>
